package org.kanger.storage.dumb2;
import java.nio.file.*;
import java.util.*;
import org.kanger.*;
import org.kanger.command.*;
import org.kanger.interfaces.IMind;
import org.kanger.interfaces.internal.IData;
import org.kanger.ContextNativeBranchInspection.*;

/** Actual prepared child/complete trusted member views/retained rollback ownership, without new writer decisions. */
final class ContextNativePendingInspectionMatrix {
    static int checks;
    static void require(boolean b,String why){++checks;if(!b)throw new AssertionError(why);}
    interface Attempt{void run()throws Exception;}
    static void reject(Attempt a,String why)throws Exception{boolean failed=false;try{a.run();}catch(Exception expected){failed=true;}require(failed,why);}
    static ContextNativeCandidateInspection.Limits limits(){return new ContextNativeCandidateInspection.Limits(1000,8,16,64000000,500000,64000000,64000000,4096);}
    static void command(ContextNativeCandidateLeaseMatrix.Fixture f,String text)throws Exception{new CanonicalCommandProcessor().execute(new CommandParser().parse(text),f.user);}
    static ContextProductionInventory inventory(ContextNativeCandidateLeaseMatrix.Fixture f,Mind mind)throws Exception{return ContextProductionInventory.inspect(mind,f.db.getContextId(),f.db.getRevision(),true,Collections.emptyList(),1000);}
    static void physical(ContextNativeCandidateLeaseMatrix.State before,ContextNativeCandidateLeaseMatrix.Fixture f)throws Exception{require(f.db.getRevision()==before.revision&&before.fingerprint.equals(inventory(f,f.mind).fingerprint),"explicit release preserves physical parent knowledge/revision; presentation lifecycle is separate");}
    static void stable(Result r){require(r.status==Status.STABLE_SUPPLIED&&r.proposed!=null&&r.oppositions.isEmpty(),r.phase+": "+r.reason);}
    static Map<UUID,View> views(Result r){Map<UUID,View> out=new LinkedHashMap<>();for(CutView cut:r.foreign)for(View v:cut.members)require(out.put(v.context,v)==null,"each physical native member reported exactly once");return out;}
    static void exact(ContextNativeCandidateLeaseMatrix.Fixture f,Result r)throws Exception{Map<UUID,View> actual=views(r);require(actual.size()==f.db.dmzTopology().size(),"whole physical topology, not first-member routing address");for(ContextConnection c:f.db.dmzTopology()){ContextProductionInventory i=ContextProductionInventory.inspect(c.layer(),c.getTarget().getContextId(),c.getTarget().getRevision(),false,c.getInitialization(),1000);View v=actual.get(i.context);require(v!=null&&v.revision==i.revision&&v.fingerprint.equals(i.fingerprint)&&v.initialization.equals(i.initialization),"exact original member pin/initialization/fingerprint");}}
    static void positive()throws Exception{
        Path dir=Files.createTempDirectory("native-pending-views-");System.setProperty("user.home",dir.toString());ContextNativeCandidateLeaseMatrix.create(dir,"A","!left(1); !p(1);");ContextNativeCandidateLeaseMatrix.create(dir,"B","!right(1); !~p(1);");
        for(boolean reverse:new boolean[]{false,true})try(ContextNativeCandidateLeaseMatrix.Fixture f=new ContextNativeCandidateLeaseMatrix.Fixture(dir,"Independent"+reverse)){
            require(f.mind.compile("!anchor(1);",null,false),"physical parent anchor");f.db.connectContext(reverse?"B":"A");f.db.connectContext(reverse?"A":"B");ContextNativeCandidateLeaseMatrix.State parent=new ContextNativeCandidateLeaseMatrix.State(f);Mind child=new Mind(f.mind);
            try{require(child.compile("!local(7); !@u left(u)&&right(u)->q(u);",null,false),"actual prepared WHOLE two-assertion child batch");String fp=inventory(f,child).fingerprint;int count=inventory(f,child).primary.size();Result safe=f.db.inspectNativePendingProduction(child,limits());stable(safe);require(safe.proposed.fingerprint.equals(fp)&&inventory(f,child).primary.size()==count&&count==3,"actual child used ONCE, no candidate staging/append or omitted batch member");exact(f,safe);parent.unchanged(f);require(fp.equals(inventory(f,child).fingerprint),"diagnostic never changes pending state");
                try(ContextPendingProductionSnapshotSession lease=ContextPendingProductionSnapshotSession.open(f.db,child,1000)){ContextNativeCandidateInspection.Limits l=limits();Result audit=lease.inspectNative(new ContextNativeCandidateInspection.Limits(1000,8,16,l.preparation,l.events,l.work,1,l.capacity));require(audit.status==Status.INCOMPLETE&&audit.proposed==null&&audit.foreign.isEmpty()&&audit.oppositions.isEmpty()&&audit.phase.equals("branch-audit"),"final whole-branch audit stop has no provisional frame/refutation prefix");parent.unchanged(f);}
            }finally{f.mind.release(child);}physical(parent,f);
            ContextNativeCandidateLeaseMatrix.State beforeConflict=new ContextNativeCandidateLeaseMatrix.State(f);Mind conflicting=new Mind(f.mind);try{require(conflicting.compile("!@u left(u)&&right(u)->p(u);",null,false),"actual proposed masked collision");Result r=f.db.inspectNativePendingProduction(conflicting,limits());require(r.status==Status.REFUTED&&!r.oppositions.isEmpty(),r.phase+": "+r.reason);exact(f,r);for(Opposition o:r.oppositions)require(o.xRefuted&&o.sources.size()==4&&o.sources.stream().filter(s->s.localX).allMatch(s->s.context.equals(f.db.getContextId())&&s.view.equals("inventory:"+r.proposed.fingerprint)),"collision Sources belong to actual pending X, no detached-candidate rebasing");beforeConflict.unchanged(f);}finally{f.mind.release(conflicting);}physical(parent,f);
        }
        ContextNativeCandidateLeaseMatrix.create(dir,"TR","!@u p(u)->q(u);");ContextNativeCandidateLeaseMatrix.create(dir,"TF","!p(1);");ContextNativeCandidateLeaseMatrix.create(dir,"N","!~r(1);");
        for(boolean reverse:new boolean[]{false,true})try(ContextNativeCandidateLeaseMatrix.Fixture f=new ContextNativeCandidateLeaseMatrix.Fixture(dir,"Trusted"+reverse)){
            require(f.mind.compile("!anchor(1);",null,false),"trusted parent anchor");f.db.connectContext(reverse?"TF":"TR","own");f.db.connectContext(reverse?"TR":"TF","own");f.db.connectContext("N");ContextNativeCandidateLeaseMatrix.State parent=new ContextNativeCandidateLeaseMatrix.State(f);Mind child=new Mind(f.mind);
            try{require(child.compile("!@u q(u)->r(u);",null,false),"actual candidate over qualified shared runtime");Result refuted=f.db.inspectNativePendingProduction(child,limits());require(refuted.status==Status.REFUTED&&!refuted.oppositions.isEmpty(),refuted.phase+": "+refuted.reason);require(refuted.foreign.size()==2&&refuted.foreign.stream().anyMatch(c->"own".equals(c.trustedGroup)&&c.members.size()==2),"one logical trusted cut with BOTH original physical members");exact(f,refuted);Map<UUID,View> all=views(refuted);for(Opposition o:refuted.oppositions){require(o.sources.size()==4&&o.sources.stream().filter(s->!s.localX).map(s->s.context).distinct().count()==3,"both trusted original member Sources AND independent negative retained");for(org.kanger.ContextProductionCapture.Source s:o.sources)if(!s.localX){View v=all.get(s.context);require(v!=null&&s.revision==v.revision&&s.view.equals("inventory:"+v.fingerprint),"proof cause is full original member pin/view, never routing representative");}}
                try(ContextPendingProductionSnapshotSession lease=ContextPendingProductionSnapshotSession.open(f.db,child,1000)){f.db.applyConnectionCommand(f.mind,"TF","-p(1);");f.db.applyConnectionCommand(f.mind,"TF","!p(2);");reject(()->lease.inspectNative(limits()),"changed initialized shared member invalidates old pending lease");}
                Result safe=f.db.inspectNativePendingProduction(child,limits());stable(safe);exact(f,safe);require(safe.foreign.stream().flatMap(c->c.members.stream()).anyMatch(v->v.initialization.size()==2),"fresh shared branch uses actual member initialization, not old runtime facts");
                try(ContextPendingProductionSnapshotSession lease=ContextPendingProductionSnapshotSession.open(f.db,child,1000)){CommuneRuntime before=f.db.productionExecutionTopology().stream().filter(c->c.commune()!=null).findFirst().get().commune();f.db.connectContext("TR","own");CommuneRuntime after=f.db.productionExecutionTopology().stream().filter(c->c.commune()!=null).findFirst().get().commune();require(before==after,"same exact pinned knowledge legitimately reuses qualified commune runtime");reject(()->lease.inspectNative(limits()),"old lease still rejects replaced raw connection instance");}
                stable(f.db.inspectNativePendingProduction(child,limits()));require(f.db.getRevision()==parent.revision&&parent.fingerprint.equals(inventory(f,f.mind).fingerprint),"private member edits and pending diagnostics do not publish physical parent");
            }finally{f.mind.release(child);}
        }
        System.out.println("NATIVE_PENDING_POSITIVE independentOrders=2 trustedOrders=2 wholeBatch=true completeSharedSources=true cachedRuntimeManifest=true noSettlement=true");
    }
    static void ownership()throws Exception{
        Path dir=Files.createTempDirectory("native-pending-ownership-");System.setProperty("user.home",dir.toString());ContextNativeCandidateLeaseMatrix.create(dir,"A","!a(1);");
        try(ContextNativeCandidateLeaseMatrix.Fixture f=new ContextNativeCandidateLeaseMatrix.Fixture(dir,"X")){
            require(f.mind.compile("!anchor(1);",null,false),"ownership parent");f.db.connectContext("A");Mind child=new Mind(f.mind);try{require(child.compile("!prepared(1);",null,false),"prepared live child");ContextPendingProductionSnapshotSession closed=ContextPendingProductionSnapshotSession.open(f.db,child,1000);closed.close();reject(()->closed.inspectNative(limits()),"closed pending lease");
                try(ContextPendingProductionSnapshotSession lease=ContextPendingProductionSnapshotSession.open(f.db,child,1000)){boolean[] off={false};Thread t=new Thread(()->{try{lease.inspectNative(limits());}catch(Exception expected){off[0]=true;}});t.start();t.join();require(off[0],"native pending lease cannot cross threads");require(child.compile("!changed(2);",null,false),"actual child changes");reject(()->lease.inspectNative(limits()),"changed actual child fingerprint");}
                f.user.setCurrentMind(child);try{stable(f.db.inspectNativePendingProduction(child,limits()));}finally{f.user.setCurrentMind(f.mind);}
                try(ContextPendingProductionSnapshotSession lease=ContextPendingProductionSnapshotSession.open(f.db,child,1000)){require(f.mind.compile("!parentChanged(3);",null,false),"parent changes with live child");reject(()->lease.inspectNative(limits()),"changed physical parent");}
            }finally{f.mind.release(child);}
            reject(()->f.db.inspectNativePendingProduction(child,limits()),"released child cannot reuse historical result");Mind replacement=new Mind(f.mind);try{reject(()->f.db.inspectNativePendingProduction(child,limits()),"released child cannot impersonate replacement reservation");}finally{f.mind.release(replacement);}
            Mind first=new Mind(f.mind),second=new Mind(f.mind);try{reject(()->f.db.inspectNativePendingProduction(first,limits()),"multiple actual root reservations");}finally{f.mind.release(second);}Mind nested=new Mind(first);try{reject(()->f.db.inspectNativePendingProduction(first,limits()),"nested child reservation");}finally{first.release(nested);f.mind.release(first);}
            reject(()->f.db.inspectNativePendingProduction(f.mind,limits()),"settled parent is not an actual child");
            rollbackProbe(f);
        }
        System.out.println("NATIVE_PENDING_OWNERSHIP actualReservations=true wholeChildCurrentness=true retainedRollbackProtectedNotImported=true postSettlementStale=true");
    }
    static void rollbackProbe(ContextNativeCandidateLeaseMatrix.Fixture f)throws Exception{
        command(f,"transaction start");Mind retained=(Mind)f.user.getCurrentMind();require(retained.query("!retainedOnly(9);",null,false),"actual retained user child");long revision=f.db.getRevision();final int[] refresh={0};final Mind[] proposed={null};final ContextPendingProductionSnapshotSession[] captured={null};
        IData proxy=(IData)java.lang.reflect.Proxy.newProxyInstance(DB.class.getClassLoader(),DB.class.getInterfaces(),(object,method,args)->{
            if(method.getName().equals("validateCommit")){synchronized(f.db){f.user.setData(f.db);try{Mind pending=(Mind)args[0];if(pending.getNext()==f.mind&&f.mind.requirePendingValidationChild(pending)!=null){++refresh[0];proposed[0]=pending;ContextPendingProductionSnapshotSession lease=ContextPendingProductionSnapshotSession.open(f.db,pending,1000);try{Result r=lease.inspectNative(limits());stable(r);require(r.proposed.fingerprint.equals(inventory(f,pending).fingerprint)&&!r.proposed.fingerprint.equals(inventory(f,retained).fingerprint),"rollback validates ACTUAL refresh target, retained knowledge never proposed X");require(retained.compile("!changedRetained(10);",null,false),"controlled retained sibling mutation");reject(()->lease.inspectNative(limits()),"retained inventory guard still enforced by native path");}finally{lease.close();}captured[0]=ContextPendingProductionSnapshotSession.open(f.db,pending,1000);stable(captured[0].inspectNative(limits()));}f.db.validateCommit((IMind)args[0]);}finally{f.user.setData((IData)object);}}return null;}
            try{return method.invoke(f.db,args);}catch(java.lang.reflect.InvocationTargetException error){throw error.getCause();}
        });
        f.user.setData(proxy);try{command(f,"transaction rollback");}finally{f.user.setData(f.db);}
        require(refresh[0]==1&&f.user.getCurrentMind()==f.mind&&f.db.getRevision()==revision,"actual native rollback/refresh completes once, no publication");require(inventory(f,f.mind).primary.stream().noneMatch(r->r.origin.contains("retainedOnly")||r.origin.contains("changedRetained")),"retained private child data discarded, never imported into physical X");reject(()->captured[0].inspectNative(limits()),"captured refresh lease expires after actual settlement");captured[0].close();reject(()->f.mind.requirePendingValidationChild(proposed[0]),"private rollback sibling scope cannot outlive settlement");
    }
}
